import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxChip,
  JxButton,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'archived';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const PAGE_SIZE = 5;

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'default' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  archived: { label: 'В архиве', tone: 'default' },
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'archived'];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекстная лаборатория', quota: 82, status: 'active' },
  { id: 'p2', name: 'Портал документации', quota: 47, status: 'active' },
  { id: 'p3', name: 'Мобильный клиент', quota: 95, status: 'paused' },
  { id: 'p4', name: 'Аналитика событий', quota: 31, status: 'active' },
  { id: 'p5', name: 'Импорт из CRM', quota: 12, status: 'archived' },
  { id: 'p6', name: 'Витрина отчётов', quota: 64, status: 'active' },
  { id: 'p7', name: 'Очередь уведомлений', quota: 73, status: 'paused' },
  { id: 'p8', name: 'Сервис биллинга', quota: 58, status: 'active' },
  { id: 'p9', name: 'Старый лендинг', quota: 5, status: 'archived' },
  { id: 'p10', name: 'Поиск по базе знаний', quota: 88, status: 'paused' },
  { id: 'p11', name: 'Экспорт в хранилище', quota: 26, status: 'active' },
  { id: 'p12', name: 'Песочница интеграций', quota: 41, status: 'archived' },
];

export default function ProjectQuotaPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(STATUS_ORDER);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const removeStatus = (status: ProjectStatus) => {
    setStatuses((prev) => prev.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(STATUS_ORDER);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}>
        {statuses.length === 0 ? (
          <span style={{ color: 'var(--jx-text-3)' }}>Все статусы сняты</span>
        ) : (
          statuses.map((status) => (
            <JxChip key={status} active removable onRemove={() => removeStatus(status)}>
              {STATUS_META[status].label}
            </JxChip>
          ))
        )}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные статусы не подходит ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column' }}>
            {visible.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 0',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <span style={{ flex: 1, minWidth: 0 }}>{project.name}</span>
                <JxProgressCircle
                  value={project.quota}
                  showValue
                  aria-label={`Заполненность квоты проекта ${project.name}`}
                />
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </li>
            ))}
          </ul>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

